#!/usr/bin/env python3
"""Autorenwerkzeug: Markusevangelium Kapitel 9–16 – Befunde, Deutungen, Grundsätze, Anwendungen, offene Fragen,
Beziehungen, Hintergrund zu Abschnitten, Kapitel-Zusammenfassungen und Studie; jeweils mit Züridüütsch-Lokalisierung.

Abgrenzung: Hintergrund zum ganzen Buch steht in BG-MRK-BOOK-0001/-0002 (Verfasser/Zeit; Markusschlüsse) und wird hier
nicht wiederholt. Die Studie zu [[MRK.3.20-MRK.3.35]] (FIND-MRK-0001…0005, STUDY-MRK-0001) bleibt unverändert; Kapitel 1–8
haben eigene IDs ab 1001. Der Kontext CTX-MARK-READERS-0070 wird nur verwendet, nie geschrieben: run() liest ihn aus der
Datei und gibt ihn unverändert weiter, sodass _lib.write nichts ändert.

Abschnitte: Jede Aussage nennt den Versbereich, auf den sie sich bezieht; zugeordnet wird die kleinste vorhandene
Texteinheit (data/text-units/TU-MRK-…), die ihn ganz enthält, sonst die Kapiteleinheit. Aussagen über kapitelübergreifende
Bereiche (z. B. [[MRK.8.27-MRK.10.52]]) hängen an der Einheit ihres Kernverses.
Zählungen: nach den MACULA-Lemmata zum SBLGNT (data/annotations/MACULA-SBLGNT-MRK-0nn.json). Die Tokens des SBLGNT
führen den kürzeren Markusschluss unter [[MRK.16.8]]; Zählungen bis 16,8 schliessen ihn nur ein, wo ausdrücklich gesagt.
Handschriftenangaben: aus den CNTR-Transkriptionen (data/witness-texts/CNTR-GA…-MRK.json), maschinell gelesen, nicht
am Faksimile geprüft.

Aufruf: python3 scripts/authoring/markus_study_b.py
KI-Entwurf (Claude) vom 2026-10-14 auf Wunsch von Andi Neck; keine fachliche Prüfung erfolgt.
"""
import json
import re
import sys
import pathlib

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
from _lib import D  # noqa: E402

TAGS = ["TAG-MARK"]
CHAPTERS = {9: "TU-MRK-009-001-050", 10: "TU-MRK-010-001-052", 11: "TU-MRK-011-001-033", 12: "TU-MRK-012-001-044",
            13: "TU-MRK-013-001-037", 14: "TU-MRK-014-001-072", 15: "TU-MRK-015-001-047", 16: "TU-MRK-016-001-020"}
_UNITS = sorted(p.stem for p in (D / "text-units").rglob("TU-MRK-*.json"))
CTX_READERS = "CTX-MARK-READERS-0070"
CTX_JESUS = "CTX-GALILEE-0030"


def U(ch, v1, v2=None):
    """Kleinste vorhandene Texteinheit, die Kapitel ch, Verse v1–v2 ganz enthält; sonst die Kapiteleinheit."""
    v2 = v2 or v1
    best = None
    for uid in _UNITS:
        m = re.fullmatch(r"TU-MRK-(\d{3})-(\d{3})-(\d{3})", uid)
        if m and int(m[1]) == ch and int(m[2]) <= v1 and int(m[3]) >= v2:
            if best is None or int(m[3]) - int(m[2]) < best[0]:
                best = (int(m[3]) - int(m[2]), uid)
    return best[1] if best else CHAPTERS[ch]


MAC = "Zählung nach den MACULA-Lemmata zum SBLGNT."
MAC_G = "Zellig nach de MACULA-Lemmata zum SBLGNT."
CNTR = ("Handschriftenangaben aus den CNTR-Transkriptionen, maschinell ausgewertet und nicht am Faksimile geprüft; "
        "Schreibweisen der Handschriften (Itazismen, Abkürzungen) sind nicht normalisiert.")
CNTR_G = ("Handschrifte-Aagaabe us de CNTR-Transkriptione, maschinell uusgwärtet und nöd am Faksimile prüeft; "
          "d Schriibwiise vo de Handschrifte (Itazisme, Abchürzige) sind nöd normalisiert.")

